namespace ohao::caustics {

namespace {

using F4 = Vector<float, 4>;

F4 f4(float x, float y, float z, float w) {
    F4 v{};
    v.x = x;
    v.y = y;
    v.z = z;
    v.w = w;
    return v;
}
F4 f4(const V3& v, float w = 0.0f) { return f4(v[0], v[1], v[2], w); }

struct Io {
    F4 rows[32]{};
};

Io base(float op, const Tri* tri, const V3* p, const V3* L) {
    Io io;
    io.rows[0] = f4(op, 0, 0, 0);
    if (tri) {
        io.rows[1] = f4(tri->p0, tri->c[0]);
        io.rows[2] = f4(tri->e1, tri->c[1]);
        io.rows[3] = f4(tri->e2, tri->c[2]);
        io.rows[4] = f4(tri->n0);
        io.rows[5] = f4(tri->a1);
        io.rows[6] = f4(tri->a2);
    }
    if (p) io.rows[7] = f4(*p);
    if (L) io.rows[8] = f4(*L);
    return io;
}

void runItem(Io& io, std::vector<F4>* mesh = nullptr) {
    GlobalParams_0 globals{};
    globals.io_0.data = io.rows;
    globals.io_0.count = 32;
    if (mesh) {
        globals.mesh_0.data = mesh->data();
        globals.mesh_0.count = mesh->size();
    }
    ComputeVaryingInput range{};
    range.startGroupID = {0, 0, 0};
    range.endGroupID = {1, 1, 1};
    ::run(&range, nullptr, &globals);
}

} // namespace

MapResult manifoldMap(const Tri& tri, const V3& p, const V3& L, V2 uv) {
    Io io = base(0, &tri, &p, &L);
    io.rows[9] = f4(uv[0], uv[1], 0, 0);
    runItem(io);
    MapResult r;
    r.ok = io.rows[13].z != 0.0f;
    r.sigma = {io.rows[13].x, io.rows[13].y};
    r.du = {io.rows[14].x, io.rows[14].y};
    r.dv = {io.rows[14].z, io.rows[14].w};
    r.y = {io.rows[15].x, io.rows[15].y, io.rows[15].z};
    r.n = {io.rows[16].x, io.rows[16].y, io.rows[16].z};
    return r;
}

bool manifoldSolve(const Tri& tri, const V3& p, const V3& L, V2 target, float tol, V2& uv) {
    Io io = base(1, &tri, &p, &L);
    io.rows[0].y = tol;
    io.rows[9] = f4(target[0], target[1], 0, 0);
    runItem(io);
    uv = {io.rows[13].x, io.rows[13].y};
    return io.rows[13].z != 0.0f;
}

V2 manifoldDrawSlope(V2 alphas, float slope2, float minSlope2, const V3& u, float& density) {
    Io io = base(2, nullptr, nullptr, nullptr);
    io.rows[0].z = slope2;
    io.rows[11].x = minSlope2;
    io.rows[9] = f4(0, 0, alphas[0], alphas[1]);
    io.rows[10] = f4(u);
    runItem(io);
    density = io.rows[13].z;
    return {io.rows[13].x, io.rows[13].y};
}

float manifoldSlopeDensity(V2 alphas, float slope2, float minSlope2, V2 sigma) {
    Io io = base(3, nullptr, nullptr, nullptr);
    io.rows[0].z = slope2;
    io.rows[11].x = minSlope2;
    io.rows[9] = f4(sigma[0], sigma[1], alphas[0], alphas[1]);
    runItem(io);
    return io.rows[13].x;
}

bool manifoldTriangleTest(const Tri& tri, const V3& p, const V3& L, V2 sigma) {
    Io io = base(5, &tri, &p, &L);
    io.rows[9] = f4(sigma[0], sigma[1], 0, 0);
    runItem(io);
    return io.rows[13].x != 0.0f;
}

bool manifoldDiscTest(const V3& boxMin, const V3& boxMax, const V3& axis, float halfAngle, const V3& c, V2 sigma,
                      const V3& p, const V3& L) {
    Tri tri{};
    tri.c = c;
    Io io = base(6, &tri, &p, &L);
    io.rows[9] = f4(sigma[0], sigma[1], 0, 0);
    io.rows[10] = f4(boxMin);
    io.rows[11] = f4(boxMax);
    io.rows[12] = f4(axis, halfAngle);
    runItem(io);
    return io.rows[13].x != 0.0f;
}

bool manifoldConeTest(const V3& boxMin, const V3& boxMax, const V3& axis, float halfAngle, const V3& p, const V3& L,
                      float thetaSigma) {
    Io io = base(4, nullptr, &p, &L);
    io.rows[0].w = thetaSigma;
    io.rows[10] = f4(boxMin);
    io.rows[11] = f4(boxMax);
    io.rows[12] = f4(axis, halfAngle);
    runItem(io);
    return io.rows[13].x != 0.0f;
}

CertResult manifoldCertify(const Tri& tri, const V3& p, const V3& L, V2 target, V2 lo, V2 hi) {
    Io io = base(7, &tri, &p, &L);
    io.rows[9] = f4(target[0], target[1], 0, 0);
    io.rows[10] = f4(lo[0], lo[1], 0, 0);
    io.rows[11] = f4(hi[0], hi[1], 0, 0);
    runItem(io);
    CertResult r;
    r.roots = static_cast<int>(io.rows[13].x);
    r.undecided = static_cast<int>(io.rows[13].y);
    r.boxes = static_cast<int>(io.rows[13].z);
    r.uv[0] = {io.rows[14].x, io.rows[14].y};
    r.uv[1] = {io.rows[14].z, io.rows[14].w};
    r.uv[2] = {io.rows[15].x, io.rows[15].y};
    r.uv[3] = {io.rows[15].z, io.rows[15].w};
    return r;
}

namespace {
Io cellIo(float op, const MappedTri& m, const Cell& cell, const V3& p, const V3& L) {
    Io io = base(op, &m.tri, &p, &L);
    io.rows[17] = f4(m.t0, m.sign);
    io.rows[18] = f4(m.ta1);
    io.rows[19] = f4(m.ta2);
    io.rows[20] = f4(m.uv0[0], m.uv0[1], m.uvA[0], m.uvA[1]);
    io.rows[21] = f4(m.uvB[0], m.uvB[1], cell.origin[0], cell.origin[1]);
    io.rows[22] = f4(cell.size[0], cell.size[1], 0, 0);
    io.rows[23] = f4(cell.c00);
    io.rows[24] = f4(cell.c10);
    io.rows[25] = f4(cell.c01);
    io.rows[26] = f4(cell.c11);
    return io;
}
} // namespace

CellMapResult manifoldCellMap(const MappedTri& m, const Cell& cell, const V3& p, const V3& L, V2 st) {
    Io io = cellIo(15, m, cell, p, L);
    io.rows[9] = f4(0, 0, st[0], st[1]);
    runItem(io);
    CellMapResult r;
    r.ok = io.rows[13].z > 0.5f;
    r.sigma = {io.rows[13].x, io.rows[13].y};
    r.J = {io.rows[14].x, io.rows[14].y, io.rows[14].z, io.rows[14].w};
    r.uv = {io.rows[15].x, io.rows[15].y};
    return r;
}

CertResult manifoldCertifyCell(const MappedTri& m, const Cell& cell, const V3& p, const V3& L, V2 target, bool* defined) {
    Io io = cellIo(14, m, cell, p, L);
    io.rows[9] = f4(target[0], target[1], 0, 0);
    runItem(io);
    CertResult r;
    r.roots = static_cast<int>(io.rows[13].x);
    r.undecided = static_cast<int>(io.rows[13].y);
    r.boxes = static_cast<int>(io.rows[13].z);
    if (defined) *defined = io.rows[13].w > 0.5f;
    r.uv[0] = {io.rows[14].x, io.rows[14].y};
    r.uv[1] = {io.rows[14].z, io.rows[14].w};
    r.uv[2] = {io.rows[15].x, io.rows[15].y};
    r.uv[3] = {io.rows[15].z, io.rows[15].w};
    return r;
}

CellPolyResult manifoldCellPoly(const MappedTri& m, const Cell& cell, const V3& p, const V3& L, V2 sigma, V2 st) {
    Io io = cellIo(16, m, cell, p, L);
    io.rows[9] = f4(sigma[0], sigma[1], st[0], st[1]);
    std::vector<F4> grids(18);
    runItem(io, &grids);
    CellPolyResult r;
    r.ok = io.rows[14].z > 0.5f;
    r.F = {io.rows[13].x, io.rows[13].y};
    r.mu = {io.rows[13].z, io.rows[13].w};
    r.direct = {io.rows[14].x, io.rows[14].y};
    for (int k = 0; k < 9; ++k) {
        const F4 a = grids[size_t(k)], b = grids[size_t(9 + k)];
        r.F1[size_t(4 * k)] = a.x;
        r.F1[size_t(4 * k + 1)] = a.y;
        r.F1[size_t(4 * k + 2)] = a.z;
        r.F1[size_t(4 * k + 3)] = a.w;
        r.F2[size_t(4 * k)] = b.x;
        r.F2[size_t(4 * k + 1)] = b.y;
        r.F2[size_t(4 * k + 2)] = b.z;
        r.F2[size_t(4 * k + 3)] = b.w;
    }
    return r;
}

CellRootsResult manifoldCellRoots(const MappedTri& m, const Cell& cell, const V3& p, const V3& L, V2 sigma,
                                  int maxBoxes) {
    Io io = cellIo(17, m, cell, p, L);
    io.rows[0].y = float(maxBoxes);
    io.rows[9] = f4(sigma[0], sigma[1], 0, 0);
    runItem(io);
    CellRootsResult r;
    r.roots = static_cast<int>(io.rows[13].x);
    r.undecided = static_cast<int>(io.rows[13].y);
    r.boxes = static_cast<int>(io.rows[13].z);
    r.defined = io.rows[13].w > 0.5f;
    r.st[0] = {io.rows[14].x, io.rows[14].y};
    r.st[1] = {io.rows[14].z, io.rows[14].w};
    r.st[2] = {io.rows[15].x, io.rows[15].y};
    r.st[3] = {io.rows[15].z, io.rows[15].w};
    r.st[4] = {io.rows[16].x, io.rows[16].y};
    r.overflow = static_cast<int>(io.rows[16].z);
    return r;
}

Enclosure manifoldEnclose(const Tri& tri, const V3& p, const V3& L, V2 lo, V2 hi, bool constraint, V2 target) {
    Io io = base(8, &tri, &p, &L);
    io.rows[0].y = constraint ? 1.0f : 0.0f;
    io.rows[9] = f4(target[0], target[1], 0, 0);
    io.rows[10] = f4(lo[0], lo[1], 0, 0);
    io.rows[11] = f4(hi[0], hi[1], 0, 0);
    runItem(io);
    Enclosure e;
    e.sx = {io.rows[13].x, io.rows[13].y};
    e.sy = {io.rows[13].z, io.rows[13].w};
    e.dsxdu = {io.rows[14].x, io.rows[14].y};
    e.dsxdv = {io.rows[14].z, io.rows[14].w};
    e.dsydu = {io.rows[15].x, io.rows[15].y};
    e.dsydv = {io.rows[15].z, io.rows[15].w};
    e.defined = static_cast<int>(io.rows[16].x);
    return e;
}

PairResult manifoldCertifyPair(const Tri& t1, const Tri& t2, const V3& X, const V3& L, float eta, V2 s1, V2 s2) {
    Io io = base(9, &t1, &X, &L);
    io.rows[8].w = eta;
    io.rows[9] = f4(s1[0], s1[1], s2[0], s2[1]);
    io.rows[17] = f4(t2.p0, t2.c[0]);
    io.rows[18] = f4(t2.e1, t2.c[1]);
    io.rows[19] = f4(t2.e2, t2.c[2]);
    io.rows[20] = f4(t2.n0);
    io.rows[21] = f4(t2.a1);
    io.rows[22] = f4(t2.a2);
    runItem(io);
    PairResult r;
    r.roots = static_cast<int>(io.rows[23].x);
    r.undecided = static_cast<int>(io.rows[23].y);
    r.boxes = static_cast<int>(io.rows[23].z);
    for (int k = 0; k < 4; ++k) r.x[k] = {io.rows[24 + k].x, io.rows[24 + k].y, io.rows[24 + k].z, io.rows[24 + k].w};
    return r;
}

WalkResult manifoldWalkPair(const std::vector<Tri>& tris, const V3& X, const V3& L, float eta, V2 s1, V2 s2,
                            const V3& seedDir, bool certify) {
    std::vector<F4> mesh;
    mesh.reserve(tris.size() * 6);
    for (const Tri& t : tris) {
        mesh.push_back(f4(t.p0, t.c[0]));
        mesh.push_back(f4(t.e1, t.c[1]));
        mesh.push_back(f4(t.e2, t.c[2]));
        mesh.push_back(f4(t.n0));
        mesh.push_back(f4(t.a1));
        mesh.push_back(f4(t.a2));
    }
    Io io = base(certify ? 12 : 13, nullptr, &X, &L);
    io.rows[0].y = float(tris.size());
    io.rows[8].w = eta;
    io.rows[9] = f4(s1[0], s1[1], s2[0], s2[1]);
    io.rows[10] = f4(seedDir);
    runItem(io, &mesh);
    WalkResult r;
    r.found = io.rows[23].x != 0.0f;
    r.steps = static_cast<int>(io.rows[23].y);
    r.roots = static_cast<int>(io.rows[23].z);
    r.undecided = static_cast<int>(io.rows[23].w);
    r.x = {io.rows[24].x, io.rows[24].y, io.rows[24].z, io.rows[24].w};
    r.entry = static_cast<int>(io.rows[25].x);
    r.exit = static_cast<int>(io.rows[25].y);
    r.slopeDet = io.rows[25].z;
    return r;
}

} // namespace ohao::caustics
